// Fade the chosen screen to black, then block until it is fully black
StartBlackFadeOut <- function ( _screen, _frame )
{
	CMND_BLACK_FADE_OUT(_screen, _frame);

	while (CMND_IS_BLACK_FADE(_screen))
	{
		suspend();
	}
};

// Cut both screens to black at the normal speed before a scene change
CMND_BLACK_FADE_OUT(SCREEN_AB, EV_FADE_NORMAL);
while (CMND_IS_BLACK_FADE(SCREEN_AB))
{
	suspend();
}
